"・デイリーミッションは100,000Gで何度でも引き直せる":"・Daily missions can be rerolled any number of times for 100,000G",
"・データが初期状態（リセット）のとき、「遊び方」のボタンが目立つように改良しました。":"・Made the \"How to Play\" button more noticeable when the data is at its initial (reset) state.",
"・ニセのアタリで「ゴミ」が釣れるように。ごくまれに…？":"・Fake bites can now hook \"junk\". Very rarely…?",
"・ノーマルガチャを「ガチャ」画面に統合（1回600G・毎日1回無料）":"・Merged the Normal Gacha into the \"Gacha\" screen (600G per spin, one free spin a day)",
"・ハズレの「海の宝箱」を「宝箱」に、「海はゴミ箱じゃないよ」を水辺向けの言葉に変更":"・Renamed the miss item \"Sea Chest\" to \"Chest\" and changed \"The sea isn't a trash can\" to waterside-friendly wording",
