"・実績：ヒント表示、全実績達成で「殿堂入り」":"・Achievements: hints shown, and \"Hall of Fame\" for earning them all",
"・幅のせまい端末で、ボタンや欄が2段になる問題を修正":"・Fixed buttons and fields wrapping into two rows on narrow devices",
"・新しいアイテムを１つ追加しました。":"・Added 1 new item.",
"・新しいエリアを２つ追加しました。":"・Added 2 new areas.",
"・新しい実績を追加しました。":"・Added a new achievement.",
"・新しい実績を５つ追加しました。":"・Added 5 new achievements.",
"・新しい生き物を約90種追加（全員に豆知識つき）":"・Added about 90 new creatures (all with trivia)",
"・最強アクセサリー（4枠）を追加。まき餌の値段を調整":"・Added the ultimate accessories (4 slots). Adjusted chum prices",
"・未開放エリアを「？」で表示するようにしました。":"・Locked areas are now shown as \"?\".",
"・横画面にすると「画面を縦にしてください」と表示し、縦に戻すまで操作できないように":"・In landscape, \"Please turn your screen upright\" is shown and controls stay disabled until you rotate back",
"・海を3つに分割：さざ波の海／沖合の海(Lv.14)／深淵の海(Lv.34)":"・Split the sea into three: Ripple Sea / Offshore Sea (Lv.14) / Abyssal Sea (Lv.34)",
"・深海で使える竿は、青銅・伝説・神獣のみ":"・Only Bronze, Legendary and Divine Beast rods can be used in the deep sea",
"・特殊な２つのエリアで伝説の竿の使用ができなくなりました。":"・The Legendary Rod can no longer be used in two special areas.",
"・生き物の説明・豆知識を、ためになる内容に":"・Made creature descriptions and trivia more informative",
"・結果画面の🏠も、少し待ってから押せるように":"・The 🏠 on the result screen can now be pressed after a short wait",
"・絵巻図鑑の背景を追加しました。":"・Added a background to the Emaki Zukan.",
"・網は「輪の中でタップ」に変更（大物は2回成功）":"・Nets changed to \"tap inside the ring\" (big ones need 2 successes)",
"・練習は毎回ルール説明つき。ミニゲームごとに制限時間・段階的な難しさ（枚数・ボタン・石板・星の数が増える等）を追加":"・Practice shows the rules every time. Added a time limit and gradual difficulty to each mini-game (more cards, buttons, slates, stars, etc.)",
"・練習中のBGMはメニューのまま（別タブに移動してもボス曲が鳴らない）":"・Practice BGM stays as the menu's (the boss theme no longer plays when you switch tabs)",
"・設定にバイブレーション機能を追加しました。":"・Added a vibration feature to Settings.",
"・設定に隠しコマンド機能を追加しました。":"・Added a hidden-command feature to Settings.",
"・設定のUIを調整しました。":"・Adjusted the Settings UI.",
"・設定の「隠しコマンド」欄が、アプデ情報を開くと2段になる問題を修正":"・Fixed the \"Hidden Commands\" row in Settings wrapping to two lines when update info is opened",
"・設定（音・難易度・バイブなど）が保存され、次回起動時も引き継がれるように":"・Settings (sound, difficulty, vibration, etc.) are now saved and carried over to the next launch",
"・遊び方に「ミニゲーム練習」を追加（スコアが高いほど難しく。10ラウンド・20ラウンドでごほうびG）":"・Added \"Mini-game Practice\" to How to Play (harder with higher scores; bonus G at 10 and 20 rounds)",
"・遊び方に追記文章を追加しました。":"・Added extra text to How to Play.",
"・遊び方を短く。「練習」で竿→大物→網を体験":"・Shortened How to Play. Experience rod → big catch → net in \"Practice\"",
"・釣りゲーム中に音声がオフにできない問題を修正しました。":"・Fixed an issue where sound couldn't be turned off during fishing.",
"・難易度を「簡単／通常／難しい」から選べる":"・Difficulty can be chosen from \"Easy / Normal / Hard\"",
"・音の有無アイコンを追加し、変更しました。":"・Added and changed the sound on/off icon.",
"・魚影の向きを正しい向きに統一。ベニザケのファイル名を修正":"・Unified the facing direction of fish shadows. Fixed Sockeye Salmon's file name",
"・魚影を実物サイズに。画像を先読みして表示を安定":"・Fish shadows are now life-size. Preloads images for stable display",
"・黄金郷はLv.100、神獣界はLv.250で開放":"・El Dorado unlocks at Lv.100, the Divine Beast Realm at Lv.250",
"・２つ実績を解除した際、重複する不具合を修正しました。":"・Fixed a bug where unlocking two achievements caused duplicates.",
"・🌋 火山エリア解放":"・🌋 Volcano area unlocked",
