"オジサン":"Ojisan Goatfish",
"あごの下に2本のヒゲがある魚。名前も見た目も、なんだかオジサン。":"A fish with two whiskers under its chin. Both the name and the look say \"middle-aged guy\".",
"正式名ではなく、ヒメジ科の魚の呼び名。あごのヒゲで砂の中のエサを探すよ。":"Not an official name, but what goatfish (family Mullidae) are called. It finds food in the sand with its chin whiskers.",
"電源から生き物まで、線をつなごう！":"Connect the line from the power source to the creature!",
"影の正体は？":"Whose shadow is it?",
"手配書の生き物を探せ！":"Find the creature on the WANTED poster!",
"同じ色を作ろう！":"Make the same color!",
"おいかけ":"Follow",
"ためうち":"Charge Shot",
"ちゅうもん":"Order",
"ねこまた":"Nekomata",
"つちぐも":"Tsuchigumo",
"がしゃどくろ":"Gashadokuro",
"ちょうちん":"Chochin",
"からかさ":"Karakasa",
"うみぼうず":"Umibozu",
"お守り×3を手に入れた":"Got 3 Charms",
"特製まき餌×5を手に入れた":"Got 5 Special Chum",
"20,000ゴールドを手に入れた":"Got 20,000 Gold",
"EXP×1.5が30分つづく":"EXP ×1.5 for 30 minutes",
"大物チャンスが20分つづく":"Big Catch Chance for 20 minutes",
"ゴールド×1.5が30分つづく":"Gold ×1.5 for 30 minutes",
"お守り":"Charm",
"※クリアするたびに、少しずつ難しくなります":"* It gets a little harder each time you clear it",
"・ミニゲーム練習の一覧を、図鑑のように横に並べる形に変更。タップすると、タイトル・記録・ゲーム開始ボタンの画面が出る":"・The mini-game practice list is now a Zukan-style grid. Tap one to see its title, your record and a Start button",
"タップすると、記録とスタートボタンが出ます。":"Tap one to see its record and Start button.",
"きろくなし":"No record",
"まだ記録なし":"No record yet",
"🏆 ベストスコア":"🏆 Best Score",
"▶ ゲーム開始":"▶ Start Game",
"いろいろなエリア":"Various areas",
"🎍 季節イベントのミニゲームは、その季節だけ遊べます":"🎍 Seasonal event mini-games can only be played during their season",
"特殊":"Special",
"イベント":"Event",
"図鑑にも「特殊エリア」のタブが増えました。":"A \"Special\" tab has also been added to the Zukan.",
"図鑑にも「イベントエリア」のタブが増えました。":"An \"Event\" tab has also been added to the Zukan.",
"季節に関係なく、いつでも遊べます。":"It can be played any time, regardless of season.",
"バグ？":"Bug?",
"ハロー、ワールド！":"Hello, World!",
"ここは 0 と 1 でできた海。":"This is a sea made of 0s and 1s.",
"……バグ？ いいえ、仕様です。":"…A bug? No, it's a feature.",
"ちいさな住人":"Tiny Resident",
"ちいさな世界へ、ようこそ！":"Welcome to the tiny world!",
"きみの体の中にも、人間の細胞と同じくらいの数の細菌が住んでいるんだって。":"They say about as many bacteria live in your body as there are human cells.",
"……こっそり、手をふってるよ。":"…They're waving at you on the sly.",
"博士":"The Professor",
"実験に失敗はつきものじゃ。":"Failure is part of every experiment.",
