"……ところで、さっきの爆発は、きみかね？":"…By the way, was that explosion just now you?",
"目玉の少年":"The Eyeball Boy",
"おや、人間かい？":"Oh? A human?",
"こんな夜ふけに川で釣りとは、なかなか肝がすわっているね。":"Fishing in a river this late at night? You've got guts.",
"……ほら、うしろ。":"…Look, behind you.",
