"・特殊エリアに必要レベルを設定（サイバーシー Lv.120／ミクロの海 140／理科実験室 160／妖怪の川 180／回転ずしレーン 200／海賊の入り江 220）":"・Added required levels for Special Areas (Cyber Sea Lv.120 / Micro Sea 140 / Science Lab 160 / Yokai River 180 / Conveyor Sushi Lane 200 / Pirates' Cove 220)",
"・特殊エリアに、ちょっとしたひみつの仕掛けを追加…？":"・Added a little secret to each Special Area…?",
"・場所移動に、フィルター（通常／ガチャ／特殊／イベント）を追加":"・Added a filter to Change Area (Normal / Gacha / Special / Event)",
"・はじめは、特殊エリア・季節イベントの図鑑タブと場所は表示されません。合言葉でエリアを解放すると、図鑑のタブと場所移動のタブが増えます":"・At first, the Special Area and Seasonal Event Zukan tabs and area tabs are hidden. Unlock an area with a secret word and the Zukan and Change Area tabs appear",
"・データ削除は、すべて消える「完全リセット」に。図鑑コンプ後の「2周目（転生）」のときだけ、拾った手紙・ミニゲーム練習記録・季節イベントの図鑑が残る":"・Deleting data is now a full reset that erases everything. Only on a \"2nd playthrough (reincarnation)\" after completing the Zukan are your letters, mini-game practice records and Seasonal Event Zukan kept",
"・隠しコマンドを追加（開発者用コマンドを大幅に追加）":"・Added hidden commands (many new developer commands)",
"なるほどね！":"I see!",
"スシローは、ネタが大きくて種類もほうふ！":"Sushiro has big cuts of fish and a huge variety!",
"タッチパネルで頼むのも楽しいよね。":"Ordering on the touch panel is fun too.",
"くら寿司は、サイドメニューが大充実！":"Kura Sushi has a great side-menu lineup!",
"「ビッくらポン！」のガチャも楽しいよね。":"The \"Bikkura Pon!\" capsule game is fun too.",
"はま寿司は、お手ごろ価格で何度も行きたくなる！":"Hama Sushi is so affordable, you'll want to go again and again!",
"お寿司いがいのメニューも多いよね。":"And it has lots of non-sushi dishes too.",
"かっぱ寿司は、食べ放題など楽しい企画がいっぱい！":"Kappa Sushi has fun events like all-you-can-eat!",
"ラーメンやデザートもおいしいよね。":"Their ramen and desserts are great too.",
"魚べいは、お寿司が「ビューン」とレーンで届く！":"At Uobei, your sushi zooms right to you on the lane!",
"ワクワクするよね。":"It's so exciting.",
"どこのお店にも、そのお店だけの良さがあるよね。":"Every restaurant has its own charm.",
"大きすぎる！ 小さく囲んで":"Too big! Circle a smaller area",
"・色混ぜの色を絵の具のように修正（黄＋青＝緑）／ミクロの海は、ぐるっと1周なぞるだけで囲めるように。画面ぜんぶを囲むのはNG／回転ずしのお皿が重ならないよう修正":"・Fixed Color Mixing to blend like paint (yellow + blue = green) / In Micro Sea, just draw one loop to circle germs (circling the whole screen no longer works) / Conveyor Sushi plates no longer overlap",
"・特殊エリアのひみつは、画面下の「さいきんの3匹」を3秒以内に5回タップ。「とじる」ボタンでキャラごと消える":"・Special Area secrets: tap the \"Latest 3 catches\" box 5 times within 3 seconds. The Close button dismisses the character too",
"ありがとう！これからもよろしく！":"Thank you! Looking forward to more!",
"・回転ずしのレーンを2本に戻した（お皿は重ならない）":"・Conveyor Sushi is back to 2 lanes (plates never overlap)",
"・生き物の説明から、いらない「、」「。」を削除":"・Removed unnecessary punctuation from creature descriptions",
"・生き物を入手した時／魚影が来た時／図鑑の「なでなで」で、生き物が泳ぐように動く（図鑑を見ているだけの時は動きません）":"・Creatures now move as if alive when caught, when their shadow swims by, and when you pet them in the Zukan (still in the Zukan view)",
"・金額にコンマを表示／ピンゾロの超大物は、そのエリアの大物から確率で選ばれる／ゴミを拾った時の文字を大きく":"・Gold amounts now show commas / The Pinzoro jackpot catch is picked at random from the area's big fish / Larger text when you pick up trash",
"・手紙の言葉は、特殊エリアは紫・イベントエリアはオレンジの色で表示":"・Letter words are shown in purple for Special Areas and orange for Event Areas",
"・スマホによって画面が小さくなる問題を修正（ミニゲームの画面を大きく表示）／特殊エリアのひみつを発動中に、後ろで釣りが進んでしまう問題を修正":"・Fixed the UI looking small on some phones (larger mini-game screen) / Fixed fishing continuing in the background while triggering a Special Area secret",
"✅ 入力ずみ　⬜ まだ入力していない":"✅ Entered　⬜ Not entered yet",
"・「拾った手紙」に、入力ずみ（✅）／まだ（⬜）のチェックを表示。並びは「アイテムなど→特殊エリア→イベントエリア」の順に自動で整列":"・\"Letters Found\" now shows ✅ (entered) / ⬜ (not yet). Letters are sorted automatically: items → Special Areas → Event Areas",
"・「拾った手紙」に、入力ずみ（✅）かまだ（⬜）かを表示":"・The \"Letters found\" list now shows whether you've entered each word (✅ entered / ⬜ not yet)",
"・手紙は、白文字（アイテム）→ 特殊エリア → イベントエリアの順に、自動で並びかわる":"・Letters are sorted automatically: white (items) → Special Areas → Event Areas",
