"・設定に「⚙ 詳しい設定」（＋ボタンで開く）を追加":"・Added \"⚙ Advanced Settings\" to Settings (open it with the + button)",
"・文字の大きさ（小／ふつう／大／特大）を変えられるように":"・You can now change the text size (Small / Normal / Large / X-Large)",
"・ドットの見え方（じどう／くっきり／なめらか）を追加。ドット絵のあらさ対策として、縮んで見える絵は初期設定「じどう」でなめらかに表示":"・Added a pixel-art style option (Auto / Crisp / Smooth). To reduce the rough look of pixel art, pictures shown smaller than their original size are now smoothed by default (\"Auto\")",
"・生き物の動き／画面のゆれ／天気エフェクトを、ON・OFFできるように":"・Creature motion, screen shake and weather effects can now be turned ON/OFF",
"・セーブデータのバックアップ（コードをコピー／コードから復元）を追加":"・Added save data backup (copy code / restore from code)",
"🌟 あそびやすさ":"🌟 Quality of Life",
"・はじめて遊ぶとき、「かんたん設定」（文字の大きさ・音・むずかしさ）が出るように":"・A quick setup (text size, volume, difficulty) now appears on first launch",
"・バックアップのおすすめ（7日に1回、そっと声をかけます）と、前回のバックアップ日の表示を追加":"・Added a gentle backup reminder (about once a week) and the last backup date",
"・新しいバージョンがあるとき、再読み込みをすすめるおしらせを追加":"・Added a notice that suggests reloading when a new version is available",
"・「釣りの操作補助」（判定をゆるくする）を追加。むずかしさとは別に選べます":"・Added \"Fishing Assist\" (more lenient timing), separate from difficulty",
"・ミニゲームに3回続けて失敗すると、次のバトルが少しやさしくなるように":"・After 3 minigame losses in a row, the next battle becomes a little easier",
"・色混ぜゲームに、色の名前を表示する設定を追加":"・Added a setting to show colour names in the colour-mixing game",
"・10,000G以上の買い物の前に確認が出るように（設定でOFF可）":"・A confirmation now appears before purchases of 10,000G or more (can be turned off)",
"・図鑑のエリアボタンに「あと◯匹」を表示。未入手のカードをタップするとヒントが出る":"・The Zukan area button shows how many are left; tap an undiscovered card for a hint",
"・連続ログインボーナスを追加。ミッションに、天気・ミニゲーム・ゴミのお題を追加":"・Added a login streak bonus and new missions (weather, minigames, trash)",
"・結果画面に「📷」ボタンを追加。釣った生き物の画像を保存・共有できる":"・Added a 📷 button on the result screen to save/share an image of your catch",
"・「あそんだ記録」（統計）、不具合報告用の情報コピー、省電力モードを追加":"・Added a Stats screen, a bug-report info copy button and a Power Saver mode",
"・タイトル画面の「アンケート」ボタンを、画面のはしに移動。ご意見・不具合の報告もここから":"・Moved the title-screen \"Survey\" button to the screen edge. Feedback and bug reports go there too",
